const entradas=$input.all();
if(entradas.length!==1) throw new Error('Receber um evento normalizado por execução; chamador no modo each.');
const e=entradas[0].json;
if(e.evento?.tipo!=='instalacao' || !['instalado','repositorios_adicionados'].includes(e.evento?.acao)) return [];
if(e.meta?.origem_verificada!==true || e.meta?.validacao?.valido!==true || e.meta?.versao_evento!==1 || !Number.isSafeInteger(e.meta?.tenant_id) || e.meta.tenant_id<=0 || !/^[0-9a-f-]{36}$/i.test(e.meta?.id_evento||'')) throw new Error('Evento sem validação/autenticação do Core.');
if(!Array.isArray(e.instalacao?.repositorios) || e.instalacao.acao!==e.evento.acao) throw new Error('Instalação normalizada inválida.');
const repos=[...new Set(e.instalacao.repositorios)];
if(repos.some(r=>typeof r!=='string'||!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(r))) throw new Error('Lista de repositórios inválida; evento inteiro recusado antes de efeitos.');
const config={check_nome:'',app_id:null,trello_habilitado:false,quadro_id:'CONFIGURE_ID_QUADRO_TRELLO',quadro_nome:'CONFIGURE_NOME_QUADRO_TRELLO',slack_habilitado:false,slack_canal_id:'CONFIGURE_ID_CANAL_SLACK'};
return repos.map(repositorio=>({json:{meta:e.meta,acao:e.evento.acao,conta:e.instalacao.conta,repositorio,config,trello:{status:config.trello_habilitado?'consultar':'desabilitado'}}}));

function classificar(evidencia, configuracao) {
 const base={versao:1,status:'verificacao_indisponivel',pronto_fluxo_protegido:false,fonte:'github_rest',simulado:false,check_obrigatorio:false,acao_necessaria:'Disponibilizar consulta autenticada de proteção no backend ou credencial GitHub no nó de leitura; definir o nome exato do Check publicado pelo aPRova.'};
 if(evidencia?.simulado===true) return {...base,motivo:'Evidência simulada recusada no fluxo real.'};
 if(!evidencia?.branch || evidencia.status_http!==200 || !evidencia.protecao || typeof evidencia.protecao!=='object') return {...base,motivo:'Proteção não pôde ser consultada; HTTP 401/403/404, timeout ou branch desconhecida não comprovam ausência de proteção.',status_http:evidencia?.status_http??null};
 if(!configuracao.check_nome || !Number.isSafeInteger(configuracao.app_id) || configuracao.app_id<=0) return {...base,motivo:'Nome e identidade do Check ainda não configurados; publicação do backend é provisória.'};
 const p=evidencia.protecao;
 if(!Object.hasOwn(p,'required_status_checks')) return {...base,motivo:'Resposta de proteção incompleta.'};
 const r=p.required_status_checks;
 if(r!==null && (!r || !Array.isArray(r.checks))) return {...base,motivo:'Resposta sem identidade dos checks obrigatórios.'};
 const encontrado=r?.checks?.find(c=>c.context===configuracao.check_nome && c.app_id===configuracao.app_id);
 if(!encontrado) return {...base,status:'check_obrigatorio_pendente',motivo:'O Check do aPRova não consta como obrigatório para esta branch e GitHub App.',acao_necessaria:'Administrador: exigir o Check '+configuracao.check_nome+' do aPRova na proteção da branch. Nenhuma configuração é alterada por este fluxo.'};
 if(p.enforce_admins?.enabled!==true) return {...base,status:'check_obrigatorio_pendente',check_obrigatorio:true,motivo:'Check obrigatório, mas proteção não inclui administradores.',acao_necessaria:'Administrador: habilitar a aplicação da proteção também aos administradores e revisar os bypasses.'};
 return {...base,status:'protecao_confirmada',pronto_fluxo_protegido:true,check_obrigatorio:true,motivo:'Consulta real confirmou Check obrigatório vinculado ao GitHub App e proteção aplicada aos administradores.',acao_necessaria:null,status_http:200};
}
const c=$('05 | Resolver branch de destino').item.json; const evidencia={branch:c.branch,status_http:$json.statusCode??null,protecao:$json.body??null,simulado:false}; return {json:{...c,protecao:classificar(evidencia,c.config)}};

const c=$('08 | Interpretar proteção real').item.json; const b=$json.body; const nome=c.repositorio;
let trello={status:'indisponivel',motivo:'Consulta do quadro/listas sem confirmação; nenhuma lista criada.'};
if($json.statusCode===200 && b?.id===c.config.quadro_id && b.name===c.config.quadro_nome && b.closed===false && Array.isArray(b.lists)){
 const listas=b.lists.filter(l=>l.idBoard===b.id && l.name?.toLowerCase()===nome.toLowerCase());
 trello=listas.length===0?{status:'criar',nome}:listas.length===1 && listas[0].closed===false?{status:'reutilizada',lista_id:listas[0].id,nome:listas[0].name}:{status:'pendente',motivo:'Lista arquivada ou nome ambíguo; revisar manualmente, sem criar duplicata.'};
} return {json:{...c,trello}};

const c=$json; const p=c.protecao;
const rotulos={protecao_confirmada:'Proteção confirmada',check_obrigatorio_pendente:'Check obrigatório pendente',verificacao_indisponivel:'Verificação indisponível'};
const texto=['aPRova — Onboarding de Repositório','Repositório: '+c.repositorio,'Branch de destino: '+(c.branch||'não identificada (consulta GitHub indisponível)'),'Verificação: '+rotulos[p.status],p.motivo,'Pronto para o fluxo protegido: '+(p.pronto_fluxo_protegido?'sim':'não confirmado'),'Trello: '+c.trello.status+(c.trello.lista_id?' — lista '+c.trello.lista_id:''),p.acao_necessaria?'Ação necessária: '+p.acao_necessaria:'',c.trello.motivo||''].filter(Boolean).join('\n');
return {json:{...c,resumo_slack:texto,notificacao_slack:{status:c.config.slack_habilitado?'pendente':'desabilitada'}}};
